// SmartHelmet/Software/src/pages/Dashboard.jsx

import Sidebar from '../components/Sidebar';
import Header from '../components/Header';
import WorkerStatusCard from '../components/WorkerStatusCard';
import SensorCard from '../components/SensorCard';
import AlertsCard from '../components/AlertsCard';
import LiveDebugPanel from '../components/LiveDebugPanel';
import useLiveData from '../hooks/useLiveData';
import { THRESHOLDS } from '../utils/constants';

/**
 * Derive per-sensor status from the current reading using known thresholds.
 */
function getSensorStatus(reading, field) {
  if (!reading || reading[field] === null || reading[field] === undefined) return 'normal';
  const val = reading[field];

  if (field === 'temperature') {
    if (val >= THRESHOLDS.temperature.emergency) return 'emergency';
    if (val >= THRESHOLDS.temperature.warning) return 'warning';
    return 'normal';
  }
  if (field === 'gas_level') {
    if (val >= THRESHOLDS.gas_level.emergency) return 'emergency';
    if (val >= THRESHOLDS.gas_level.warning) return 'warning';
    return 'normal';
  }
  if (field === 'force') {
    if (val >= THRESHOLDS.force.emergency) return 'emergency';
    if (val >= THRESHOLDS.force.warning) return 'warning';
    return 'normal';
  }
  if (field === 'heart_rate') {
    if (val > 0 && (val <= THRESHOLDS.heart_rate.emergencyLow || val >= THRESHOLDS.heart_rate.emergencyHigh)) return 'emergency';
    if (val > 0 && (val <= THRESHOLDS.heart_rate.warningLow || val >= THRESHOLDS.heart_rate.warningHigh)) return 'warning';
    return 'normal';
  }
  return 'normal';
}

export default function Dashboard() {
  const { reading, alerts, worker, status, loading } = useLiveData();

  return (
    <div className="min-h-screen" style={{ position: 'relative', background: '#060B26' }}>
      {/* ── Video Background ───────────── */}
      <video
        autoPlay
        loop
        muted
        playsInline
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100vh',
          objectFit: 'cover',
          zIndex: 0,
          pointerEvents: 'none',
          opacity: 0.6, /* Adjust opacity here if it's too bright */
        }}
      >
        <source src="/bg-video.mp4" type="video/mp4" />
      </video>

      <Sidebar />
      <Header />

      {/* ── Main content area ─────────────────────── */}
      <main
        style={{
          marginLeft: 'var(--sidebar-width)',
          marginTop: 'var(--header-height)',
          minHeight: 'calc(100vh - var(--header-height))',
          padding: '24px 24px 24px 40px',
          position: 'relative',
          zIndex: 1,
        }}
      >
        {/* ── Row 1: Worker Status ─────────────────── */}
        <div style={{ marginBottom: 24 }}>
          <WorkerStatusCard worker={worker} status={status} reading={reading} />
        </div>

        {/* ── Row 2: Sensor Cards Grid ─────────────── */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
            gap: 20,
            marginBottom: 24,
          }}
        >
          <SensorCard
            label="Temperature"
            value={reading?.temperature}
            unit="°C"
            status={getSensorStatus(reading, 'temperature')}
            icon="🌡️"
            subtitle="Ambient mine temperature"
          />
          <SensorCard
            label="Gas Level"
            value={reading?.gas_level}
            unit="ppm"
            status={getSensorStatus(reading, 'gas_level')}
            icon="💨"
            subtitle="MQ-series gas concentration"
          />
          <SensorCard
            label="Force"
            value={reading?.force}
            unit="N"
            status={getSensorStatus(reading, 'force')}
            icon="⚡"
            subtitle="Helmet impact force"
          />
          <SensorCard
            label="Heart Rate"
            value={reading?.heart_rate}
            unit="bpm"
            status={getSensorStatus(reading, 'heart_rate')}
            icon="❤️"
            subtitle="Worker pulse rate"
          />
          <SensorCard
            label="SpO2"
            value={reading?.spo2}
            unit="%"
            status="normal"
            icon="🫁"
            subtitle="Blood oxygen saturation"
          />
          <SensorCard
            label="RSSI"
            value={reading?.rssi}
            unit="dBm"
            status="normal"
            icon="📡"
            subtitle="Beacon signal strength"
          />
        </div>

        {/* ── Row 3: Alerts ────────────────────────── */}
        <div style={{ marginBottom: 24 }}>
          <AlertsCard alerts={alerts} />
        </div>

        {/* ── Debug Panel (de-emphasized) ──────────── */}
        <div style={{ opacity: 0.6, marginTop: 32 }}>
          <LiveDebugPanel
            reading={reading}
            alerts={alerts}
            worker={worker}
            status={status}
            loading={loading}
          />
        </div>
      </main>
    </div>
  );
}
